        /* Swap cell->{key,data} and {key,data} (evict). */
        const void *tkey = cell->key;
        const void *tdata = cell->data;
        cell->key = key;
        cell->data = data;
        key = tkey;
        data = tdata;

#ifdef CKH_COUNT
        ckh->nrelocs++;
#endif

        /* Find the alternate bucket for the evicted item. */
        ckh->hash(key, hashes);
        tbucket = hashes[1] & ((1ULL << ckh->lg_curbuckets) - 1);
        if (tbucket == bucket) {
            tbucket = hashes[0] & ((1ULL << ckh->lg_curbuckets) - 1);
        }

        /* Check for a cycle. */
        if (tbucket == argbucket) {
            return true; /* Failed due to cycle. */
        }

        bucket = tbucket;
        if (!ckh_try_bucket_insert(ckh, bucket, key, data)) {
            return false; /* Successfully inserted. */
        }
    }
